from types import SimpleNamespace

# This sandbox has no network and no API key, so FakeOpenAI stands in for
# openai.OpenAI(). client.chat.completions.create(...) takes the same arguments as the
# real SDK and returns an object shaped like the real ChatCompletion response.
class _Completions:
    def __init__(self):
        self.last_request = None

    def create(self, model, messages, **kwargs):
        self.last_request = {"model": model, "messages": messages, **kwargs}
        for m in messages:
            if m.get("role") not in ("system", "user", "assistant"):
                raise ValueError("each message needs a role: 'system', 'user' or 'assistant'")
        text = "Here are 3 Python tips: use f-strings, read error messages carefully, practise every day."
        prompt_tokens = sum(len(m["content"].split()) for m in messages)
        completion_tokens = len(text.split())
        return SimpleNamespace(
            choices=[SimpleNamespace(index=0, finish_reason="stop",
                                     message=SimpleNamespace(role="assistant", content=text))],
            usage=SimpleNamespace(prompt_tokens=prompt_tokens, completion_tokens=completion_tokens,
                                  total_tokens=prompt_tokens + completion_tokens),
        )


class FakeOpenAI:
    def __init__(self, api_key=None):
        if not api_key:
            raise ValueError("api_key is required")   # the real SDK raises an OpenAIError
        self.chat = SimpleNamespace(completions=_Completions())


